import type { TextPos } from "./TextPos";

/**
 * A misspelled word with suggestions.
 */
export type SpellingHit = { 
/**
 * The word.
 */
word: string, 
/**
 * Where it starts.
 */
start: TextPos, 
/**
 * Its length in chars.
 */
len: number, 
/**
 * Corrections, best first.
 */
suggestions: Array<string>, 
/**
 * The sentence around it (the Spelling dialog's "Not in Dictionary" box).
 */
context: string, 
/**
 * The word's char offset inside `context`.
 */
context_offset: number, };
